package main

import (
	"slices"
	"sync"
	"testing"
)

type Todo struct {
	ID    int
	Title string
	Done  bool
}

type store struct {
	mu    sync.Mutex
	todos []Todo
}

// list was optimized: it no longer copies.
func (s *store) list() []Todo {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.todos
}

func TestListReturnsACopy(t *testing.T) {
	s := &store{todos: []Todo{{1, "a", false}, {2, "b", false}}}
	got := s.list()
	got[0].Title = "changed by caller"
	if !slices.Equal(s.todos, []Todo{{1, "a", false}, {2, "b", false}}) {
		t.Fatalf("store changed through the returned slice: %v", s.todos)
	}
}
